// @ts-check
// Writes the package's stylesheets after `tsc`:
// - `theme.css`: tw-animate-css, the components for Tailwind to scan (`@source`, relative to the file, so the app's
//   Tailwind finds them inside node_modules), and the Notion tokens generated by @softure-ai/theme-kit;
// - `sft-bridge.css`: copied from src/, plain CSS for the app's Tailwind.
// The tokens come from the built `tokens.js`, so TypeScript stays the only source of the theme.
//
// Usage: node scripts/build-css.mjs [distDir]   (default: the package's dist/, after tsc)
import { copyFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

import { buildThemeCss } from "@softure-ai/theme-kit";

const PACKAGE_DIR = fileURLToPath(new URL("..", import.meta.url));

/** The folders of components whose classes Tailwind has to generate, relative to `theme.css`. */
export const COMPONENT_SOURCES = ["./ui", "./notion"];

/**
 * @typedef {object} ThemeStylesheetInput
 * @property {(definition: import("@softure-ai/theme-kit").ThemeDefinition) => string} buildThemeCss the kit's generator
 * @property {import("@softure-ai/theme-kit").ThemeDefinition} theme the theme definition
 * @property {string[]} sources `@source` paths, relative to the written file or absolute
 */

/**
 * The text of `theme.css`.
 * @param {ThemeStylesheetInput} input
 * @returns {string}
 */
export function buildThemeStylesheet({ buildThemeCss, theme, sources }) {
  return [
    `@import "tw-animate-css";`,
    ...sources.map((source) => `@source ${JSON.stringify(source)};`),
    "",
    buildThemeCss(theme),
  ].join("\n");
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const distDir = resolve(process.argv[2] ?? join(PACKAGE_DIR, "dist"));
  // After `tsc`: the built tokens module is the theme's source.
  /** @type {unknown} */
  const built = await import(pathToFileURL(join(distDir, "tokens.js")).href);
  const tokens = /** @type {{ NOTION_THEME: import("@softure-ai/theme-kit").ThemeDefinition }} */ (built);
  writeFileSync(
    join(distDir, "theme.css"),
    buildThemeStylesheet({ buildThemeCss, theme: tokens.NOTION_THEME, sources: COMPONENT_SOURCES }),
  );
  copyFileSync(join(PACKAGE_DIR, "src/sft-bridge.css"), join(distDir, "sft-bridge.css"));
  console.log(`@softure-ai/theme-notion: theme.css and sft-bridge.css in ${distDir}`);
}
